import { guiaControles } from './controls-guide.js';
const $=id=>document.getElementById(id);let cfg,cb,aberto=false,guia='A PÉ';
export function iniciar(config,callbacks){cfg=config;cb=callbacks;$('pausePanel').onclick=e=>{const b=e.target.closest('[data-pausa]');if(!b)return;const [a,v]=b.dataset.pausa.split(':');if(a==='voltar')alternar(false);if(a==='guia'){guia=v;render();}if(a==='qualidade'){cb.qualidade(v);render();}};$('pausePanel').oninput=e=>{if(e.target.id==='pauseSens'){cfg.sensibilidade=+e.target.value;cb.salvar();}if(e.target.id==='pauseVol'){cfg.volume=+e.target.value/100;cb.volume(cfg.volume);cb.salvar();}};}
function render(){const conquistas=cb.conquistas();$('pausePanel').innerHTML=`<div class="pauseHead"><div><small>JOGO PAUSADO</small><h2>City Rush</h2></div><button data-pausa="voltar">Continuar</button></div>${guiaControles(guia)}<section><h3>Configurações</h3><div class="quality">${['auto','baixa','media','alta','ultra'].map(q=>`<button class="${(q==='auto'?cfg.qualidadeAuto:!cfg.qualidadeAuto&&cfg.qualidade===q)?'sel':''}" data-pausa="qualidade:${q}" title="${{auto:'Escolhe pelo aparelho e reduz sozinho se o FPS cair',baixa:'Sem sombras, resolução 100%',media:'Sombras, sem pós-processamento',alta:'Sombras, bloom e borrão de velocidade',ultra:'Resolução até 2×, sombras 2048 e maior alcance'}[q]}">${{auto:'Auto',baixa:'Baixa',media:'Média',alta:'Alta',ultra:'Ultra'}[q]}</button>`).join('')}</div><label>Sensibilidade <input id="pauseSens" type="range" min="0.5" max="2" step="0.1" value="${cfg.sensibilidade}"></label><label>Volume <input id="pauseVol" type="range" min="0" max="100" value="${Math.round(cfg.volume*100)}"></label></section><section><h3>Conquistas · ${conquistas.filter(c=>c.ok).length}/${conquistas.length}</h3><div class="achGrid">${conquistas.map(c=>`<article class="${c.ok?'ok':''}"><b>${c.ok?'🏆':'🔒'} ${c.nome}</b><small>${c.desc}</small></article>`).join('')}</div></section>`;}
export function alternar(on=!aberto){aberto=on;$('pausePanel').classList.toggle('on',on);cb.aoAbrir(on);if(on)render();}
export const estaAberto=()=>aberto;
